import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        boolean neg = buf[bp] == '-';
        if (neg) bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);  // ascending: the first player takes a[n-1], a[n-3], ...
        long diff = 0;
        for (int i = 0; i < n; i++) diff += i % 2 == 0 ? a[n - 1 - i] : -a[n - 1 - i];
        System.out.println(diff);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n := int(next())
	a := make([]int64, n)
	for i := range a {
		a[i] = next()
	}
	slices.Sort(a)
	slices.Reverse(a)
	var diff int64
	for i, v := range a {
		if i%2 == 0 {
			diff += v
		} else {
			diff -= v
		}
	}
	fmt.Println(diff)
}
